'::jsonb,'["Revisión parcial del diagnóstico histórico del PDM-OT 2020–2032: tabla 3, página PDF 61 (impresa 60), leída con su introducción municipal. Resume problemas y potencialidades de talleres participativos, no mediciones actuales.", "Las columnas de problemas y potencialidades son listas independientes: la posición en una misma fila no establece causalidad ni correspondencia entre ambas.", "No se incorporaron el puesto 11 de 333 del índice de competitividad ni el porcentaje de ocupación mencionado en el desarrollo del texto: requieren periodo y fuente verificables.", "No se importaron caracterizaciones por edad ni afirmaciones generales sobre capacidades personales o condiciones sanitarias. Las potencialidades no prueban proyectos ejecutados; falta completar la homologación del plan."]'::jsonb)
  )
  update data_vault.municipality_intelligence_profiles_v1 p
  set profile=jsonb_set(jsonb_set(jsonb_set(p.profile,
    '{public_context,planning,priorities}',r.priorities),
    '{public_context,planning,review_notes}',r.notes),
    '{public_context,planning,review_status}','"PARTIAL_VALIDATED_CONTENT"'::jsonb),updated_at=now()
  from reviewed r, public.municipalities m
  where m.country_code='GT' and not m.is_synthetic and m.municipality_code=r.code
    and p.municipality_id=m.id and p.country_code=m.country_code
    and p.profile->>'municipality_code'=r.code
    and p.profile#>>'{public_context,planning,municipality_code}'=r.code
    and p.profile#>>'{public_context,planning,document,file_id}'=r.file_id
    and p.profile#>'{public_context,planning,priorities}'='[]'::jsonb;
  get diagnostics changed=row_count;
  if changed <> 3 then raise exception 'PDM_REVIEW_CONCURRENT_CHANGE_OR_SCOPE_MISMATCH_%', changed; end if;
end $migration$;
